let _markdown = "\n\nGlobal Options [#global-options]\n\n<FeedbackBlock id=\"b359be2493ec48e9\" body=\"Shared options of Fumadocs MDX.\">\n  Shared options of Fumadocs MDX.\n</FeedbackBlock>\n\n```ts title=\"source.config.ts\"\nimport { defineConfig } from 'fumadocs-mdx/config';\n\nexport default defineConfig({\n  // global options\n});\n```\n\n<TypeTable\n  type={{\n  \"name\": \"GlobalConfig\",\n  \"description\": \"\",\n  \"entries\": [\n    {\n      \"name\": \"plugins\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"PluginOption[] | undefined\",\n      \"simplifiedType\": \"array\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"mdxOptions\",\n      \"description\": \"Configure global MDX options\",\n      \"tags\": [],\n      \"type\": \"MDXPresetOptions | (() => Promise<MDXPresetOptions>) | undefined\",\n      \"simplifiedType\": \"function | ProcessorOptions & object | object & Omit<ProcessorOptions, \\\"_ctx\\\" | \\\"remarkPlugins\\\" | \\\"rehypePlugins\\\">\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"workspaces\",\n      \"description\": \"\",\n      \"tags\": [],\n      \"type\": \"Record<string, { dir: string; config: Record<string, unknown>; }> | undefined\",\n      \"simplifiedType\": \"Record<string, object>\",\n      \"required\": false,\n      \"deprecated\": false\n    },\n    {\n      \"name\": \"experimentalBuildCache\",\n      \"description\": \"specify a directory to access & store cache (disabled during development mode).\\n\\nThe cache will never be updated, delete the cache folder to clean.\",\n      \"tags\": [],\n      \"type\": \"string | undefined\",\n      \"simplifiedType\": \"string\",\n      \"required\": false,\n      \"deprecated\": false\n    }\n  ]\n}}\n/>\n\nMDX Options [#mdx-options]\n\n<FeedbackBlock id=\"41c474fe501eccd6\" body=\"Customise the default MDX preset.\">\n  Customise the [default MDX preset](/docs/mdx/mdx).\n</FeedbackBlock>\n\n```ts title=\"source.config.ts\"\nimport { defineConfig } from 'fumadocs-mdx/config';\nimport rehypeKatex from 'rehype-katex';\nimport remarkMath from 'remark-math';\n\nexport default defineConfig({\n  mdxOptions: {\n    remarkPlugins: [remarkMath],\n    // When order matters\n    rehypePlugins: (v) => [rehypeKatex, ...v],\n  },\n});\n```\n\n<FeedbackBlock id=\"159c5134a712fd52\" body=\"Or using the minimal preset:\">\n  Or using the minimal preset:\n</FeedbackBlock>\n\n```ts title=\"source.config.ts\"\nimport { defineConfig } from 'fumadocs-mdx/config';\n\nexport default defineConfig({\n  mdxOptions: {\n    preset: 'minimal',\n    // now it accepts only MDX processor options\n  },\n});\n```\n";
